package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_factorialDouble_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testFactorialDouble_NegativeInputThrowsException() {
        try {
            MathUtils.factorialDouble(-1);
            org.junit.Assert.fail("Expected IllegalArgumentException to be thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n >= 0 for n!", e.getMessage());
        }
    }

    @Test
    public void testFactorialDouble_Zero() {
        // 0! = 1
        assertEquals(1.0, MathUtils.factorialDouble(0), DELTA);
    }

    @Test
    public void testFactorialDouble_SmallPositive() {
        // 5! = 120
        assertEquals(120.0, MathUtils.factorialDouble(5), DELTA);
    }

    @Test
    public void testFactorialDouble_LargePositive() {
        // 10! = 3628800
        assertEquals(3628800.0, MathUtils.factorialDouble(10), DELTA);
    }

    /**
     * Note: The implementation provided contains a logical contradiction:
     * if (n < 0) throw exception;
     * if (n < -21) return factorial(n);
     * The second condition (n < -21) is unreachable because n < 0 is caught first.
     * However, to maximize branch coverage for the provided code structure, 
     * we test the paths that are reachable.
     */
    @Test
    public void testFactorialDouble_BranchCoverage() {
        // Test n >= 0 path
        assertEquals(1.0, MathUtils.factorialDouble(0), DELTA);
        assertEquals(2.0, MathUtils.factorialDouble(2), DELTA);

        // Test n < 0 path (which triggers the exception)
        try {
            MathUtils.factorialDouble(-5);
        } catch (IllegalArgumentException e) {
            // Expected
        }
    }
}
